# Find preserved non-4 cells in D1
print("Preserved non-4 cells in D1 (where input=output and !=4):")
for i in range(22):
    line_i = demo1_input[i].split()
    line_o = demo1_output[i].split()
    for j in range(6):
        inp_val = int(line_i[j])
        out_val = int(line_o[j])
        if inp_val == out_val and inp_val != 4:
            print(f"D1: ({i},{j})={inp_val}")

# Find cells that became 7 in D1 (they were changed from something else to 7)
print("\nCells that became 7 in D1 (changed from other value to 7):")
for i in range(22):
    line_i = demo1_input[i].split()
    line_o = demo1_output[i].split()
    for j in range(6):
        inp_val = int(line_i[j])
        out_val = int(line_o[j])
        if inp_val != 7 and out_val == 7:
            print(f"D1: ({i},{j}) {inp_val} -> 7")
